import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[] b = new long[(int) n];
        for (int i = 0; i < b.length; i++) b[i] = Long.parseLong(next());

        Map<Long, List<Integer>> positions = new HashMap<>();
        for (int j = 0; j < n; j++) positions.computeIfAbsent(b[j], key -> new ArrayList<>()).add(j);
        Map<Long, Integer> used = new HashMap<>();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            int k = used.getOrDefault(a[i], 0);
            sb.append(positions.get(a[i]).get(k)).append(i + 1 < n ? " " : "\n");
            used.put(a[i], k + 1);
        }
        System.out.print(sb);
    }
}
